REVOKE UPDATE ON public.profiles FROM authenticated;
CREATE OR REPLACE FUNCTION public.save_profile(p_name text DEFAULT NULL,p_birthday date DEFAULT NULL,p_anniversary date DEFAULT NULL,p_photo_path text DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in first'; END IF; IF p_name IS NULL OR length(trim(p_name)) NOT BETWEEN 1 AND 40 OR p_anniversary IS NULL OR p_anniversary>current_date OR p_birthday>current_date THEN RAISE EXCEPTION 'Enter a valid name and dates that are not in the future'; END IF; IF p_photo_path IS NOT NULL AND split_part(p_photo_path,'/',1)<>auth.uid()::text THEN RAISE EXCEPTION 'Invalid photo'; END IF; INSERT INTO public.profiles(id,name,birthday,anniversary,photo_path) VALUES(auth.uid(),trim(p_name),p_birthday,p_anniversary,p_photo_path) ON CONFLICT(id) DO UPDATE SET name=excluded.name,birthday=excluded.birthday,anniversary=excluded.anniversary,photo_path=excluded.photo_path; UPDATE public.relationships SET anniversary=p_anniversary WHERE id=public.my_relationship(); END $$;
REVOKE ALL ON FUNCTION public.save_profile(text,date,date,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.save_profile(text,date,date,text) TO authenticated;